from lesson_helpers import *
from lesson_figures import figure,CSS
titles=['Définition','Épidémiologie','Physiopathologie','Démarche clinique','Anamnèse','Examen clinique','Syndromes','Diagnostic positif','Explorations','Arbre diagnostique et diagnostics différentiels','Prise en charge','Prévention, suivi et pronostic','Points clés','Pièges']
a='''<template id="ch-G24"><div class="chap"><div class="chap-head"><div class="code">G24 · Mouvements anormaux · S08 · CIM-10-GM suisse2024</div><h1>Dystonie</h1><span class="status">Sol-Neurologie-G24 · Auto-relecture IA documentée · Sans validation médicale humaine</span></div><div class="tabs ui" role="tablist"><button role="tab" aria-controls="pA" data-p="pA" aria-selected="true">⚕ Pathologie et prise en charge</button><button role="tab" aria-controls="pE" data-p="pE" aria-selected="false">🔬 Examens complémentaires</button><button role="tab" aria-controls="pS" data-p="pS" aria-selected="false">⚛ Sciences fondamentales spécialisées</button><button role="tab" aria-controls="pP" data-p="pP" aria-selected="false">💊 Pharmacologie</button></div>'''+CSS+'''<div class="panel" id="pA"><nav class="toc ui"><b>Plan monographique</b><ol>'''+''.join('<li><a href="#g24-'+str(i)+'">'+t+'</a></li>' for i,t in enumerate(titles,1))+'''</ol></nav><div class="chap-body" data-semiology-clinical="G24">'''
a+=sec('question','Même posture, même cause et même traitement ?', '''<p><b>Vignettes fictives.</b> Une personne ne peut plus écrire sans que sa main prenne une position inhabituelle. Une autre tourne involontairement la tête et l’améliore brièvement en touchant son menton. Un patient présente une posture cervicale et une difficulté à parler après un antiémétique. Un enfant marche moins bien en fin de journée. Ces situations appellent une description précise et une recherche de cause, pas le même traitement automatique.</p><p>L’enjeu est de reconnaître le phénomène, rechercher une urgence respiratoire ou systémique, décrire les deux axes et ne pas manquer une cause traitable. Les médicaments symptomatiques, les injections et les traitements causaux ont des indications et des limites différentes.</p>'''+key('Décrire le mouvement, établir le contexte et choisir la décision qui change les soins.'),('INT-MDS-DEF','INT-MDS-AXIS1','EU-ERN-CHILD','FI-PAS','CH-PROFILES'))
a+=sec(1,'1. Définition : un trouble du mouvement, puis une étiologie et un code', '''<p>Selon le consensus international2025, la '''+w('definition','dystonie')+''' se manifeste par des mouvements ou postures anormaux, soutenus ou intermittents, souvent organisés en un '''+w('pattern','motif répétitif')+'''. Ils peuvent être tremblants ou saccadés, être déclenchés ou aggravés par l’action et s’accompagner d’un débordement. La torsion est fréquente, mais n’est pas indispensable : les spasmes palpébraux ou laryngés en font partie.</p><p>Ce n’est ni le nom d’une maladie musculaire unique ni une preuve d’étiologie génétique. Une contraction involontaire produit la posture ; la localisation du mécanisme peut être un réseau nerveux. Une rétraction mécanique, une spasticité ou un autre mouvement anormal peuvent lui ressembler.</p>'''+table(['OFS2024','Libellé ou portée'],[['G24.0','Dystonie médicamenteuse ; inclusion dyskinésie tardive, médicament à identifier par code supplémentaire au besoin'],['G24.1','Dystonie idiopathique familiale ; inclusion idiopathique sans autre indication'],['G24.2','Dystonie idiopathique non familiale'],['G24.3','Torticolis spasmodique'],['G24.4','Dystonie bucco-faciale idiopathique'],['G24.5','Blépharospasme'],['G24.8 / G24.9','Autres dystonies / dystonie sans précision']])+'''<p>La '''+w('classification','classification clinique')+''' ne remplace pas la nomenclature. G24 exclut la paralysie cérébrale athétosique vers G80.3, qui inclut la paralysie cérébrale dystonique. G24.3 exclut le torticolis sans précision M43.6. Aucun sous-code.6 ou.7 n’est inventé ; un signe de dystonie ne suffit pas seul à choisir le code final.</p>''',('INT-MDS-DEF','INT-MDS-AXIS1','CH-CIM','CH-CIM-BOUND'))
a+=sec(2,'2. Épidémiologie : distinguer une estimation générale et une enquête historique', '''<p>L’étude ESDE publiée en2000 a recherché les cas de dystonie primaire identifiés par des neurologues d’adultes spécialisés dans huit pays européens. Pour1996–1997, la prévalence brute annuelle de période était de152par million, soit15,2pour100000 ; les auteurs la considèrent sous-estimée en raison de cas non repérés. Le résumé primaire, et non l’article intégral sous abonnement, a été lu.</p><p>La page d’information USZ mise à jour en février2026 donne un ordre de grandeur général de40pour100000. Elle n’expose pas une enquête suisse récente de code G24. Ces valeurs ont des populations, des méthodes et des époques différentes : elles ne forment pas deux mesures interchangeables d’une incidence nationale.</p><p>Une dystonie peut débuter à tout âge. Les formes précoces ou étendues orientent davantage vers certaines causes génétiques ou métaboliques ; les formes focales tardives sont souvent idiopathiques. Il s’agit d’orientations, pas d’exclusions. L’âge du début moteur, la famille et les signes associés comptent davantage qu’une moyenne isolée.</p>''',('EU-ESDE','CH-USZ-EPI','INT-MDS-AXIS1','INT-MDS-AXIS2'))
a+=sec(3,'3. Physiopathologie : une commande en réseau et un effecteur périphérique', '''<p>Le contrôle d’un geste associe cortex, noyaux gris, thalamus et autres voies sensorimotrices. Les mécanismes de dystonie sont hétérogènes ; une IRM normale n’exclut pas le phénomène. Une dystonie ne suppose donc pas une lésion visible du pallidum ni une destruction dopaminergique universelle.</p><p>Au muscle normal, l’acétylcholine libérée par le motoneurone déclenche une activité électrique, la mobilisation du calcium puis la contraction. Une toxine botuliqueA peut diminuer cette transmission périphérique par clivage deSNAP-25. Elle réduit un effet moteur local sans démontrer ni corriger automatiquement la cause centrale.</p>'''+figure('neck')+'''<p>Dans certaines formes '''+w('dopa','dopa-sensibles')+''', un trouble de synthèse de neurotransmetteur est traitable. '''+w('gch1','voie du cofacteur et de la dopamine')+''' illustrent un mécanisme différent d’une lésion acquise ; la tyrosinehydroxylase utiliseBH4 pour formerL-DOPA. Ce raisonnement n’autorise pas la même dose ni le même produit chez tout enfant dystonique.</p><p>Une cause métabolique telle que Wilson, une exposition médicamenteuse, une lésion ou un mécanisme immunitaire demandent leur propre démarche. L’hypothèse mécanistique ne suffit pas à prescrire chélateur, immunothérapie ou stimulation.</p>''',('INT-MDS-AXIS2','NORMAL-MUSCLE','BOT-MECH','NORMAL-GCH1','NORMAL-TH','EU-EASL-SYM','IMG-NECK'))
a+=sec(4,'4. Démarche clinique : trier avant de classer', '''<ol><li><b>Évaluer la sécurité.</b> Difficulté à respirer ou déglutir, altération de conscience, fièvre avec aggravation rapide, contractions diffuses épuisantes ou défaillance générale demandent un circuit urgent.</li><li><b>Reconnaître le phénomène.</b> Décrire mouvement, posture, tâche et variations ; chercher les ressemblances avec un autre trouble moteur ou une cause mécanique.</li><li><b>Décrire l’axeI.</b> Début, famille, régions, temporalité, phénoménologie et signes associés.</li><li><b>Orienter l’axeII.</b> Expositions, causes traitables, imagerie et investigations adaptées, avec expertise si nécessaire.</li><li><b>Fixer un plan mesurable.</b> Cause, symptômes, autonomie, douleur, tolérance et suivi.</li></ol><p>Une '''+w('acute','dystonie aiguë médicamenteuse')+''' et une '''+w('storm','crise dystonique sévère')+''' ne se confondent pas avec une dystonie focale stable. Après une injection de toxine, une faiblesse, dysphagie ou dyspnée nouvelle peut aussi signaler une diffusion et nécessite une évaluation immédiate.</p>''',('EU-ERN-ADULT','EU-ERN-CHILD','EU-ERN-TX','FI-PAS','BOT-IMMUNO','CH-HUG'))
a+=sec(5,'5. Anamnèse : le début moteur, la tâche et les expositions réelles', '''<p>L’''' +w('history','histoire chronologique')+''' précise première région atteinte, âge du début moteur, installation aiguë/subaiguë/progressive et évolution. Rechercher variations diurnes, effet du sommeil, activités déclenchantes et '''+w('task','spécificité d’une tâche')+'''. Une douleur ou une gêne peut précéder le diagnostic, mais ne date pas nécessairement le début du phénomène moteur.</p><p>Noter antécédents familiaux et signes pouvant passer inaperçus chez les proches. Une histoire négative ne supprime pas une cause génétique : expression variable, cas sporadique ou variant de novo peuvent expliquer ce constat. Le conseil génétique ne repose pas seulement sur un ancien numéroDYT.</p><p>L’''' +w('drug','exposition médicamenteuse')+''' inclut neuroleptiques, antiémétiques et modifications récentes, avec dose, durée, forme et dernière prise réelle. Le métoclopramide peut provoquer une dystonie aiguë même après une prise ; sa FI distingue aussi dyskinésie tardive et syndrome malin. Demander traitements reçus ailleurs, automédication, toxiques et événements neurologiques.</p><p>Évaluer déglutition, voix, vision, marche, écriture, repas, sommeil, douleur, travail et vécu psychologique. Une anxiété n’établit pas une cause fonctionnelle ; elle peut être une conséquence ou une comorbidité.</p>''',('INT-MDS-AXIS1','INT-MDS-AXIS2','INT-MDS-PHENO','FI-PAS','CH-USZ-CLIN','CH-HUG'))
a+=sec(6,'6. Examen clinique : observer le motif dans plusieurs conditions', '''<p>L’''' +w('exam','examen du mouvement')+''' commence au repos puis pendant posture et action. Observer la tâche concernée si elle est possible et sûre : écriture, geste instrumental, parole ou marche. Comparer régions, côté, amplitude, rythme et direction ; rechercher répétition du même motif plutôt que tout appeler spasme.</p><p>Un '''+w('geste','geste atténuateur')+''' peut réduire brièvement la posture sans force mécanique importante ; il soutient la description sans être obligatoire ni absolument spécifique. Chercher '''+w('overflow','débordement')+''' vers une région voisine et '''+w('mirror','dystonie en miroir')+''' lors d’une tâche controlatérale. Ce dernier phénomène diffère d’un simple mouvement en miroir.</p>'''+figure('clinical')+'''<p>Mobiliser passivement pour distinguer posture soutenue et '''+w('fixed','posture fixée')+''', tout en respectant douleur et sécurité. Examiner force, tonus, réflexes, coordination, nerfs crâniens, cognition et signes systémiques. Documenter ce qui est constaté et ce qui reste incertain ; un enregistrement audiovisuel exige consentement dans le parcours réel.</p><p>Pour une forme cervicale, décrire tête, cou et épaules au lieu d’imaginer un seul muscle responsable à partir de la direction visible. L’anatomie et, si indiqués, les examens de guidage complètent l’examen avant traitement spécialisé.</p>''',('INT-MDS-PHENO','INT-MDS-AXIS1','CH-PROFILES','CH-HUG','FI-XEOMIN','IMG-CLINICAL'))
a+=sec(7,'7. Syndromes : distribution, temporalité et signes associés', '''<p>La '''+w('distribution','distribution2025')+''' utilise sept régions de référence : face supérieure, face inférieure, cou avec épaules, larynx, membres supérieurs, tronc et membres inférieurs. Focale : une région. Segmentaire : deux ou trois régions contiguës, hors hémidystonie. Multifocale : deux ou trois régions non contiguës, dont deux bras ou deux jambes.</p><p>Hémidystonie : membre supérieur et inférieur d’un même côté, avec ou sans autres régions. Généralisée : distribution dépassant les schémas segmentaire/multifocal sans être hémidystonie. Les exemples du consensus comprennent <b>tronc avec deux autres régions</b>, ou <b>trois/quatre membres sans tronc</b>. Une règle mécanique « plus de trois régions » serait incorrecte. La convention de dystonie cervicale focale malgré épaules est conservée.</p><p>La forme '''+w('combined','isolée ou combinée')+''' se définit selon les autres manifestations pertinentes : myoclonies distinctes, parkinsonisme, signes pyramidaux, atteinte cognitive/développementale ou systémique. Un mouvement dystonique tremblant n’est pas automatiquement un tremblement indépendant. Douleur ou trouble anxieux seuls ne changent pas une forme isolée en combinée.</p>'''+figure('motor')+'''<p>Enfin, distinguer aiguë médicamenteuse, '''+w('tardive','forme tardive')+''', spécifique d’une tâche, fluctuante et paroxystique. Le même code peut englober des mécanismes et des conduites différents ; décrire avant de traiter.</p>''',('INT-MDS-DISTR','INT-MDS-AXIS1','INT-MDS-PHENO','FI-PAS','CH-CIM','IMG-MOTOR'))
a+=sec(8,'8. Diagnostic positif : clinique, avec un niveau de certitude explicite', '''<p>Le diagnostic de dystonie s’appuie sur un motif moteur compatible, observé dans ses conditions de survenue et relié à l’histoire. Geste atténuateur, action, débordement ou répétition aident ; aucun n’est exigé dans toutes les formes. Un blépharospasme peut être fait de spasmes brefs et une dystonie laryngée ne présente pas nécessairement une torsion visible.</p><p>La '''+w('etiology','cause étiologique')+''' vient ensuite. Une exposition pertinente, une maladie documentée, une lésion concordante ou un résultat génétique interprété peuvent soutenir l’étiologie. Ni imagerie normale, ni simple variant de signification incertaine, ni âge adulte ne démontrent une origine unique. Les qualificatifs idiopathique, génétique, acquis et combiné ont des sens distincts.</p><p>Le consensus2025 range la dystonie fonctionnelle parmi les ressemblances diagnostiques. Cela n’autorise pas à conclure sur le stress, le sexe, une douleur importante ou un examen complémentaire normal. Une expertise clinique adaptée recherche les arguments positifs et les diagnostics concurrents.</p><p>L’hypothèse, ses éléments et ses limites sont expliqués au patient. Le code est choisi après cette caractérisation et peut nécessiter les catégories d’une maladie causale plutôt qu’un G24 automatique.</p>''',('INT-MDS-DEF','INT-MDS-PHENO','INT-MDS-AXIS2','EU-ERN-ADULT','CH-CIM-BOUND'))
a+=sec(9,'9. Explorations : adaptées au syndrome et aux causes traitables', '''<p>L’''' +w('imaging','IRM cérébrale')+''' recherche une cause structurale selon âge, début et signes associés. Une forme focale idiopathique peut avoir une imagerie sans anomalie détectable. Le circuit pédiatrique ERN comporte une IRM puis un bilan orienté ; la version documentaire2026 reprend une branche issue de2015, distincte de la révision adulte.</p><p>La '''+w('genetics','génétique')+''' se choisit avec phénotype, âge, famille et conseil adapté. Un panel ou séquençage n’est pas un diagnostic à interpréter sans contexte. Avant stimulation dans une dystonie monogénique suspectée, la revue européenne2026 soutient une place systématique de l’évaluation génétique dans un bilan multidisciplinaire.</p><p>Rechercher une '''+w('wilson','maladie de Wilson')+''' quand le tableau le justifie, notamment chez un sujet jeune ou avec signes hépatiques/neuropsychiatriques. Céruloplasmine, cuivre urinaire, examen ophtalmologique et génétique s’intègrent à une démarche de centre ; un seul résultat ne suffit pas. Le bilan métabolique pédiatrique et l’essai de dopa-sensibilité relèvent d’un protocole spécialisé.</p><p>Électromyographie et échographie peuvent aider à distinguer certains phénomènes ou guider un traitement, mais ne prouvent pas seules l’étiologie centrale. En crise sévère, rechercher complications et causes déclenchantes sans attendre un bilan génétique.</p>''',('EU-ERN-ADULT','EU-ERN-CHILD','EU-EASL-DX','EU-DBS-COUNSEL','INT-MDS-AXIS2','FI-XEOMIN'))
a+=sec(10,'10. Arbre diagnostique et diagnostics différentiels', '''<ol><li><b>Urgence ?</b> Protéger les fonctions vitales et faire évaluer un '''+w('airway','trouble respiratoire ou de déglutition')+''', une crise diffuse ou une complication de toxine.</li><li><b>Phénomène dystonique ?</b> Décrire motif, action, repos, mobilité passive et signes accompagnateurs ; envisager mimics mécaniques, autre trouble moteur ou fonctionnel.</li><li><b>Exposition ou cause acquise ?</b> Reconstituer ordonnance et chronologie, événements neurologiques et signes systémiques.</li><li><b>Cause traitable ou génétique ?</b> Choisir investigations adaptées à âge, famille et phénotype, sans panel ou médicament identique pour tous.</li><li><b>Plan et suivi ?</b> Séparer traitement causal, symptomatique, retentissement et codage.</li></ol><p>Spasticité, faiblesse pyramidale, tremblement indépendant, myoclonies, tics, rétraction et torticolis non dystonique se discutent selon examen. Une crise oculogyre après médicament et un blépharospasme chronique ne sont pas la même situation. Un état rigide confus/fébrile impose aussi de rechercher syndrome malin et autres défaillances.</p>''',('EU-ERN-ADULT','EU-ERN-CHILD','INT-MDS-PHENO','FI-PAS','FI-AKI','BOT-IMMUNO','CH-CIM-BOUND'))
a+=sec(11,'11. Prise en charge : cause, symptômes et fonction', '''<p><b>Cause acquise.</b> Revoir le produit responsable avec l’équipe et traiter une maladie identifiée. En dystonie aiguë médicamenteuse, le '''+w('akineton','bipéridène')+''' peut relever de la FI suisse dans un cadre évalué et surveillé ; il ne constitue pas une réponse universelle à toute dyskinésie tardive, qu’il peut aggraver.</p><p><b>Forme focale gênante.</b> Les injections de '''+w('toxin','toxine botulique')+''' sont une option majeure, avec sélection des muscles, indication et compétences adaptées. Les '''+w('units','unités propres au produit')+''' et les intervalles ne se convertissent pas mécaniquement. La '''+w('dilution','concentration après reconstitution')+''' permet seulement de vérifier un volume après choix clinique, pas d’inventer une dose.</p><p><b>Forme étendue ou réfractaire.</b> Les options orales et la '''+w('dbs','stimulation cérébrale profonde')+''' se discutent en équipe spécialisée. La cause génétique, la durée, les déformations et les objectifs fonctionnels influencent la décision ; aucun pourcentage unique ne garantit le résultat.</p><p><b>Cause traitable.</b> Dopa-sensibilité et Wilson demandent leurs propres traitements. L’essai pédiatrique de lévodopa mentionné dans le parcours européen ne rend pas Madopar conforme à sa FI suisse chez les moins de25ans : produit, statut hors indication et protocole sont vérifiés par le spécialiste.</p><p><b>Fonction.</b> Rééducation, adaptations de tâche, déglutition/voix, prise en charge de douleur, aide au travail et soutien psychosocial complètent le traitement. Les techniques non invasives du schéma ERN n’ont pas toutes une efficacité validée et ne deviennent pas une offre standard obligatoire.</p>''',('FI-AKI','FI-PAS','FI-BOTOX','FI-XEOMIN','FI-DYSPORT','FI-MAD','EU-ERN-TX','EU-DBS-COUNSEL','EU-DBS-LIMIT','EU-EASL-SYM','CH-USZ-TX'))
a+=sec(12,'12. Prévention, suivi et pronostic : mesurer ce qui compte', '''<p>Une '''+w('prevention','prévention')+''' universelle de toutes les dystonies n’est pas disponible. Il reste utile de reconnaître les expositions évitables, les effets précoces et les indications inadaptées, puis de documenter clairement l’événement et son relais. Les limites de durée de la FI du métoclopramide concernent ce produit et ses indications, pas tous les traitements neurologiques.</p><p>Le '''+w('follow','suivi')+''' décrit douleur, autonomie, tâches, voix/déglutition, participation sociale, effets indésirables et évolution de distribution. Des '''+w('scales','échelles adaptées')+''' comme TWSTRS/Tsui cervicales ou Fahn-Marsden dans des formes généralisées aident à comparer ; elles ne remplacent pas le récit et les objectifs du patient.</p><p>Après toxine, mesurer réponse maximale, durée et tolérance. Une moindre efficacité n’est pas automatiquement due à des '''+w('antibodies','anticorps neutralisants')+''' : revoir diagnostic, muscles, dose, technique et intervalle. Rechercher diffusion en cas de faiblesse, dysphagie ou dyspnée nouvelle.</p><p>Pour '''+w('child','l’enfant')+''', suivre développement et étiologie avec neuropédiatrie. Pendant '''+w('pregnancy','grossesse et allaitement')+''', vérifier chaque produit et une maladie causale éventuelle : la décision concernant une toxine diffère de la continuité d’un traitement anti-cuivre de Wilson. La trajectoire reste variable ; ni rémission définitive ni progression à date fixe n’est promise.</p>''',('CH-USZ-EPI','CH-HUG','EU-ERN-SCALES','EU-DBS-COUNSEL','BOT-IMMUNO','FI-PAS','FI-XEOMIN','FI-DYSPORT','FI-AKI','EU-EASL-SYM'))
a+=sec(13,'13. Points clés', '''<ul><li>Le motif moteur et ses conditions de survenue sont le point de départ ; une image seule ne teste pas le mouvement.</li><li>Classification2025 sur deux axes, avec distribution révisée et signes associés décrits séparément.</li><li>Exposition récente, cause traitable et urgence respiratoire ou systémique restent prioritaires.</li><li>Formes focales, étendues, tardives et combinées ne partagent pas toutes le même traitement.</li><li>FI suisses : BOTOXmai2025, Xeominmars2026, Dysportmai2026, Akinetonmai2022 ; Madoparjuin2023 pour sa limite d’indication/âge, Paspertinjanvier2020 comme médicament causal.</li><li>Doses et unités des toxines ne sont pas interchangeables ; le volume suit la concentration d’un produit identifié.</li><li>Cas et quiz de ce cours sont fictifs originaux, sans statut de questions fédérales officielles.</li></ul>''',('INT-MDS-DEF','INT-MDS-DISTR','EU-ERN-TX','FI-BOTOX','FI-XEOMIN','FI-DYSPORT','FI-AKI','FI-MAD','FI-PAS','CH-MEBEKO'))
a+=sec(14,'14. Pièges qui changent la conduite', '''<ul><li>Appeler dystonie toute posture ou tout tremblement, ou exiger une torsion visible dans chaque forme.</li><li>Considérer douleur ou anxiété comme preuve de forme combinée ou fonctionnelle.</li><li>Imposer le tronc dans toute forme généralisée, ou appliquer uniquement « plus de trois régions ».</li><li>Confondre inclusion de dyskinésie tardive dans G24.0 et indication automatique d’anticholinergique.</li><li>Transférer un nombre d’unités, un plafond ou un intervalle d’une toxine à une autre ou d’un autre pays à la FI suisse.</li><li>Présenter l’inscription AWMFseptembre2026 comme une guideline achevée, ou le schéma source2018 actualisé en2025 comme de nouveaux essais.</li><li>Déduire un mécanisme moléculaire ou un traitement d’une image isolée.</li><li>Confondre auto-relecture IA, contrôle ciblé de structure et validation médicale humaine.</li></ul>'''+trap('L’étiquette aide à organiser le raisonnement ; elle ne remplace pas la cause, la formulation, la population ou l’urgence.'),('INT-MDS-PHENO','INT-MDS-DISTR','CH-CIM','FI-AKI','FI-BOTOX','FI-XEOMIN','FI-DYSPORT','EU-AWMF-STATUS','EU-ERN-TX','IMG-CLINICAL'))
a+='</div></div>';save('a',a)
print('G24 : quatorze points monographiques rédigés après Betta réel.')
